define(['jquery'],function($){'use strict';$.widget('mage.amBaseCopyToClipboardButton',{options:{targetInputSelector:null,disableTimeout:1500},_create:function(){if($(this.options.targetInputSelector).length===0){return;}
this._bind();},_bind:function(){this._on({'click':this.clickHandler});},clickHandler:async function(){await this.copy();this.toggleDisablingByTimeout();},copy:async function(){try{await navigator.clipboard.writeText($(this.options.targetInputSelector).val());}catch(error){$(this.options.targetInputSelector).select();document.execCommand("copy");}},toggleDisablingByTimeout:function(){$(this.element).prop('disabled',true);setTimeout(()=>{$(this.element).prop('disabled',false);},this.options.disableTimeout);}});return $.mage.amBaseCopyToClipboardButton;});